# Generated by build.py from recipe.yml for recipe imap-search-by-sender-and-date. Do not edit.
set -e
cd "$(dirname "$0")"
surl --mail-domain example.com --mailbox ann@example.com:annpass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u ann@example.com:annpass --mail-from sender@example.org --mail-rcpt ann@example.com -T "mail[1-4].eml" smtp://127.0.0.1:8080/example.org
curl -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 4 FLAGS" imap://127.0.0.1:8081/INBOX
curl -s -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX?FROM%20shop%20SENTSINCE%2001-Jun-2026" --next -s -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=[3-4];SECTION=HEADER.FIELDS%20(FROM%20SUBJECT)"
kill $(jobs -p)
